+  for (let attempt = 0; attempt < 5; attempt++) {
+    try {
+      await ledger.record(order, event)
+      await mailer.receipt(order)
+      return ack()
+    } catch (err) {
+      if (!isTransient(err)) throw err
+      const wait = 250 * 2 ** attempt
+      log.warn({ orderId: order.id, attempt, wait }, 'retrying')
+      await sleep(wait)
+    }
+  }
+  log.error({ orderId: order.id }, 'gave up after 5 attempts')
+  return ack()
 }

@@ -12,9 +12,17 @@ export async function onPayment(event: PaymentEvent) {
   const order = await orders.find(event.orderId)
   if (!order) return ack()

-  await ledger.record(order, event)
-  await mailer.receipt(order)
-  return ack()
+  try {
+    await ledger.record(order, event)
+    await mailer.receipt(order)
+    return ack()
+  } catch (err) {
+    if (!isTransient(err)) throw err
+    // Redelivered by the broker with its own backoff, up to maxReceiveCount,
+    // then parked on the dead-letter queue where a human can see it.
+    log.warn({ orderId: order.id, err: err.code }, 'nacking for redelivery')
+    return nack()
+  }
 }
